const data = $json;

const categories = Array.isArray(data.categories)
  ? data.categories
  : JSON.parse(data.categories ?? "[]");

const dailyTrend = Array.isArray(data.daily_trend)
  ? data.daily_trend
  : JSON.parse(data.daily_trend ?? "[]");

const total = Number(data.total_incidents ?? 0);
const critical = Number(data.critical_incidents ?? 0);
const resolved = Number(data.resolved_incidents ?? 0);
const unresolved = Number(data.unresolved_incidents ?? 0);

const criticalPercentage = total
  ? ((critical / total) * 100).toFixed(1)
  : "0.0";

const categoryLines = categories.length
  ? categories.map(
      (item) => `- ${item.category}: ${item.count}`
    )
  : ["- No incidents recorded"];

const dailyLines = dailyTrend.length
  ? dailyTrend.map(
      (item) => `- ${item.date}: ${item.count}`
    )
  : ["- No incidents recorded"];

const observations = [];

if (total === 0) {
  observations.push(
    "No incidents were recorded in the automation incident cases during this period."
  );
} else {
  if (unresolved > 0) {
    observations.push(
      `${unresolved} incident(s) remain unresolved. Review their current status.`
    );
  }

  if (categories.length > 0) {
    observations.push(
      `The most frequent recorded category was ${categories[0].category} (${categories[0].count} incidents).`
    );
  }

  if (critical > 0) {
    observations.push(
      `${critical} critical incident(s) were recorded (${criticalPercentage}% of incidents).`
    );
  }
}

const message = [
  "OPSPILOT — DAILY INCIDENT INTELLIGENCE",
  "",
  "Reporting period: Previous 7 days",
  `Generated: ${data.generated_at}`,
  "",
  "INCIDENT SUMMARY",
  `Total: ${total}`,
  `Critical: ${critical}`,
  `Resolved: ${resolved}`,
  `Unresolved: ${unresolved}`,
  `Critical percentage: ${criticalPercentage}%`,
  "",
  "TOP INCIDENT CATEGORIES",
  ...categoryLines,
  "",
  "DAILY INCIDENT TREND",
  ...dailyLines,
  "",
  "OPERATIONAL OBSERVATIONS",
  ...observations.map((item) => `- ${item}`),
  "",
  "NEXT ACTIONS",
  "- Review recurring incident categories.",
  "- Investigate unresolved critical incidents.",
  "- Compare trends with underlying incident evidence.",
  "",
  "Note: Recurring categories indicate patterns, not proven root causes.",
  "",
  "Generated by IncidentIQ Automation Intelligence"
].join("\n");

return {
  json: {
    subject: `IncidentIQ — Daily Incident Intelligence | ${String(data.generated_at).slice(0, 10)}`,
    message,
    total_incidents: total,
    critical_incidents: critical,
    unresolved_incidents: unresolved
  }
};

if (typeof $json.id !== "string" || !$json.id.trim()) {
  throw new Error("Gmail did not return a message ID");
}

return {
  json: {
    report_type: "daily_incident_intelligence",
    delivery_confirmed: true,
    gmail_message_id: $json.id,
    completed_at: new Date().toISOString()
  }
};
